-- view: stg_payroll_lines
CREATE OR REPLACE VIEW `control-electoral-510800.staging.stg_payroll_lines` AS
-- Every column is cast through STRING first so the model works whether the bronze
-- table was loaded with schema autodetect or as all-STRING.
WITH typed AS (
  SELECT
    TRIM(CAST(payroll_line_id AS STRING))                                   AS payroll_line_id,
    TRIM(CAST(pay_run_id AS STRING))                                        AS pay_run_id,
    UPPER(TRIM(CAST(employee_id AS STRING)))                                AS employee_id,
    NULLIF(UPPER(TRIM(CAST(department_id AS STRING))), '')                  AS department_id,
    SAFE_CAST(CAST(pay_period_start AS STRING) AS DATE)                     AS pay_period_start,
    SAFE_CAST(CAST(pay_period_end AS STRING) AS DATE)                       AS pay_period_end,
    SAFE_CAST(CAST(pay_date AS STRING) AS DATE)                             AS pay_date,
    UPPER(TRIM(CAST(earning_type AS STRING)))                               AS earning_type,
    SAFE_CAST(CAST(hours AS STRING) AS NUMERIC)                             AS hours,
    SAFE_CAST(REPLACE(TRIM(CAST(amount_usd AS STRING)), ',', '') AS NUMERIC) AS amount_usd,
    CAST(amount_usd AS STRING)                                              AS amount_usd_raw,
    UPPER(TRIM(CAST(line_status AS STRING)))                                AS line_status,
    NULLIF(TRIM(CAST(voids_line_id AS STRING)), '')                         AS voids_line_id,
    SAFE_CAST(REPLACE(CAST(_ingested_at AS STRING), ' UTC', '') AS TIMESTAMP) AS ingested_at
  FROM `control-electoral-510800.looker.payroll_lines`
)

SELECT
  t.*,
  STARTS_WITH(t.employee_id, 'TEST') AS is_test_account,
  ROW_NUMBER() OVER (
    PARTITION BY t.payroll_line_id
    ORDER BY t.ingested_at DESC
  ) AS ingestion_rank
FROM typed AS t
;


-- table: dim_fiscal_calendar
CREATE OR REPLACE TABLE `control-electoral-510800.gold.dim_fiscal_calendar` AS
WITH days AS (
  SELECT d AS calendar_date
  FROM UNNEST(GENERATE_DATE_ARRAY(DATE '2024-07-01', DATE '2028-06-30', INTERVAL 1 DAY)) AS d
),

fiscal AS (
  SELECT
    calendar_date,
    DATE_TRUNC(calendar_date, MONTH)                         AS month_start_date,
    LAST_DAY(calendar_date, MONTH)                           AS month_end_date,
    EXTRACT(YEAR FROM DATE_ADD(calendar_date, INTERVAL 6 MONTH)) AS fiscal_year_num,
    MOD(EXTRACT(MONTH FROM calendar_date) + 5, 12) + 1       AS fiscal_period
  FROM days
)

SELECT
  calendar_date,
  month_start_date,
  month_end_date,
  calendar_date = month_end_date                                   AS is_month_end,
  fiscal_year_num,
  CONCAT('FY', CAST(fiscal_year_num AS STRING))                    AS fiscal_year,
  fiscal_period,
  DIV(fiscal_period - 1, 3) + 1                                    AS fiscal_quarter_num,
  CONCAT('FY', CAST(fiscal_year_num AS STRING), '-Q', CAST(DIV(fiscal_period - 1, 3) + 1 AS STRING)) AS fiscal_quarter,
  MOD(fiscal_period, 3) = 0                                        AS is_fiscal_quarter_end_month,
  fiscal_period = 12                                               AS is_fiscal_year_end_month
FROM fiscal
;

ASSERT NOT EXISTS (SELECT calendar_date FROM `control-electoral-510800.gold.dim_fiscal_calendar` GROUP BY calendar_date HAVING COUNT(*) > 1) AS 'dim_fiscal_calendar: uniqueKey(calendar_date) failed';

