-- table: fct_payroll_lines
CREATE OR REPLACE TABLE `control-electoral-510800.gold.fct_payroll_lines`
PARTITION BY DATE_TRUNC(pay_date, MONTH)
CLUSTER BY department_id, employee_id AS
WITH latest AS (
  -- Issue: some lines were ingested twice (same payroll_line_id, later _ingested_at).
  SELECT *
  FROM `control-electoral-510800.staging.stg_payroll_lines`
  WHERE ingestion_rank = 1
),

voided_line_ids AS (
  -- Issue: a VOID line is a positive-amount line that cancels an earlier POSTED line.
  -- Both the VOID line and the line it cancels are removed. The corrected amount, if any,
  -- arrives as a new POSTED line in a later pay run and is kept.
  SELECT DISTINCT voids_line_id AS payroll_line_id
  FROM latest
  WHERE line_status = 'VOID'
    AND voids_line_id IS NOT NULL
)

SELECT
  l.payroll_line_id,
  l.pay_run_id,
  l.employee_id,
  l.department_id,
  l.pay_period_start,
  l.pay_period_end,
  l.pay_date,
  DATE_TRUNC(l.pay_date, MONTH) AS pay_month,
  l.earning_type,
  l.hours,
  l.amount_usd,
  l.ingested_at
FROM latest AS l
LEFT JOIN voided_line_ids AS v
  ON v.payroll_line_id = l.payroll_line_id
WHERE l.line_status = 'POSTED'
  AND v.payroll_line_id IS NULL      -- not cancelled by a VOID
  AND NOT l.is_test_account          -- Issue: TEST-001 / TEST-002 synthetic users
;

ASSERT NOT EXISTS (SELECT payroll_line_id FROM `control-electoral-510800.gold.fct_payroll_lines` GROUP BY payroll_line_id HAVING COUNT(*) > 1) AS 'fct_payroll_lines: uniqueKey(payroll_line_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_payroll_lines` WHERE payroll_line_id IS NULL) AS 'fct_payroll_lines: nonNull(payroll_line_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_payroll_lines` WHERE pay_run_id IS NULL) AS 'fct_payroll_lines: nonNull(pay_run_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_payroll_lines` WHERE employee_id IS NULL) AS 'fct_payroll_lines: nonNull(employee_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_payroll_lines` WHERE department_id IS NULL) AS 'fct_payroll_lines: nonNull(department_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_payroll_lines` WHERE pay_date IS NULL) AS 'fct_payroll_lines: nonNull(pay_date) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_payroll_lines` WHERE earning_type IS NULL) AS 'fct_payroll_lines: nonNull(earning_type) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_payroll_lines` WHERE amount_usd IS NULL) AS 'fct_payroll_lines: nonNull(amount_usd) failed';

