-- assertion: assert_void_lines_reference_posted_lines
ASSERT NOT EXISTS (
WITH latest AS (
  SELECT * FROM `control-electoral-510800.staging.stg_payroll_lines` WHERE ingestion_rank = 1
)

SELECT
  v.payroll_line_id,
  v.voids_line_id,
  CASE
    WHEN o.payroll_line_id IS NULL           THEN 'VOID_TARGET_NOT_FOUND'
    WHEN o.line_status <> 'POSTED'           THEN 'VOID_TARGET_NOT_POSTED'
    WHEN o.employee_id <> v.employee_id      THEN 'VOID_TARGET_OTHER_EMPLOYEE'
    WHEN o.amount_usd <> v.amount_usd        THEN 'VOID_AMOUNT_MISMATCH'
  END AS problem
FROM latest AS v
LEFT JOIN latest AS o
  ON o.payroll_line_id = v.voids_line_id
WHERE v.line_status = 'VOID'
  AND (o.payroll_line_id IS NULL OR o.line_status <> 'POSTED'
       OR o.employee_id <> v.employee_id OR o.amount_usd <> v.amount_usd)

UNION ALL

SELECT payroll_line_id, voids_line_id, 'VOID_WITHOUT_TARGET_ID'
FROM latest
WHERE line_status = 'VOID' AND voids_line_id IS NULL

UNION ALL

SELECT payroll_line_id, voids_line_id, 'POSTED_LINE_WITH_VOIDS_ID'
FROM latest
WHERE line_status = 'POSTED' AND voids_line_id IS NOT NULL
) AS 'assert_void_lines_reference_posted_lines failed';

-- view: audit_payroll_line_exclusions
CREATE OR REPLACE VIEW `control-electoral-510800.gold.audit_payroll_line_exclusions` AS
WITH latest_status AS (
  SELECT payroll_line_id, line_status, voids_line_id
  FROM `control-electoral-510800.staging.stg_payroll_lines`
  WHERE ingestion_rank = 1
),

voided AS (
  SELECT DISTINCT voids_line_id AS payroll_line_id
  FROM latest_status
  WHERE line_status = 'VOID'
)

SELECT
  s.payroll_line_id,
  s.pay_run_id,
  s.employee_id,
  s.department_id,
  s.pay_date,
  s.earning_type,
  s.amount_usd,
  s.ingested_at,
  CASE
    WHEN s.ingestion_rank > 1          THEN 'DUPLICATE_INGESTION'
    WHEN s.is_test_account             THEN 'TEST_ACCOUNT'
    WHEN s.line_status = 'VOID'        THEN 'VOID_LINE'
    WHEN v.payroll_line_id IS NOT NULL THEN 'CANCELLED_BY_VOID'
    ELSE 'OTHER'
  END AS exclusion_reason
FROM `control-electoral-510800.staging.stg_payroll_lines` AS s
LEFT JOIN voided AS v
  ON v.payroll_line_id = s.payroll_line_id
LEFT JOIN `control-electoral-510800.gold.fct_payroll_lines` AS f
  ON f.payroll_line_id = s.payroll_line_id
 AND s.ingestion_rank = 1
WHERE f.payroll_line_id IS NULL
;


-- table: dim_employee_department_history
CREATE OR REPLACE TABLE `control-electoral-510800.gold.dim_employee_department_history` AS
WITH snapshots AS (
  SELECT employee_id, department_id, hire_date, DATE(loaded_at) AS loaded_date, loaded_at
  FROM `control-electoral-510800.staging.stg_employee_snapshots`
  WHERE NOT is_test_account
),

payroll_department AS (
  -- Most frequently charged cost center per employee: fallback for NULL departments.
  SELECT employee_id, department_id
  FROM `control-electoral-510800.gold.fct_payroll_lines`
  GROUP BY employee_id, department_id
  QUALIFY ROW_NUMBER() OVER (PARTITION BY employee_id ORDER BY COUNT(*) DESC, department_id) = 1
),

resolved AS (
  SELECT
    s.employee_id,
    COALESCE(s.department_id, p.department_id)                     AS department_id,
    IF(s.department_id IS NULL, 'PAYROLL_FALLBACK', 'SNAPSHOT')    AS department_source,
    s.hire_date,
    s.loaded_date,
    s.loaded_at
  FROM snapshots AS s
  LEFT JOIN payroll_department AS p USING (employee_id)
),

changes AS (
  -- Keep only snapshots where the department actually changed (gaps-and-islands).
  SELECT
    *,
    ROW_NUMBER() OVER (PARTITION BY employee_id ORDER BY loaded_at) AS snapshot_seq,
    LAG(department_id) OVER (PARTITION BY employee_id ORDER BY loaded_at) AS previous_department_id
  FROM resolved
),

kept AS (
  SELECT *
  FROM changes
  WHERE snapshot_seq = 1
     OR department_id IS DISTINCT FROM previous_department_id
)

SELECT
  employee_id,
  department_id,
  department_source,
  IF(snapshot_seq = 1, LEAST(hire_date, loaded_date), loaded_date) AS valid_from,
  COALESCE(
    DATE_SUB(LEAD(loaded_date) OVER (PARTITION BY employee_id ORDER BY loaded_at), INTERVAL 1 DAY),
    DATE '9999-12-31'
  ) AS valid_to,
  LEAD(loaded_date) OVER (PARTITION BY employee_id ORDER BY loaded_at) IS NULL AS is_current
FROM kept
;

ASSERT NOT EXISTS (SELECT employee_id, valid_from FROM `control-electoral-510800.gold.dim_employee_department_history` GROUP BY employee_id, valid_from HAVING COUNT(*) > 1) AS 'dim_employee_department_history: uniqueKey(employee_id, valid_from) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.dim_employee_department_history` WHERE employee_id IS NULL) AS 'dim_employee_department_history: nonNull(employee_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.dim_employee_department_history` WHERE department_id IS NULL) AS 'dim_employee_department_history: nonNull(department_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.dim_employee_department_history` WHERE valid_from IS NULL) AS 'dim_employee_department_history: nonNull(valid_from) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.dim_employee_department_history` WHERE valid_to IS NULL) AS 'dim_employee_department_history: nonNull(valid_to) failed';

-- table: dim_employee
CREATE OR REPLACE TABLE `control-electoral-510800.gold.dim_employee` AS
SELECT
  s.employee_id,
  s.first_name,
  s.last_name,
  CONCAT(s.first_name, ' ', s.last_name)                AS full_name,
  s.email,
  h.department_id                                       AS current_department_id,
  s.job_title,
  s.employment_type,
  s.flsa_status,
  s.employment_type IN ('FULL_TIME', 'PART_TIME')       AS is_headcount_eligible,
  s.hire_date,
  s.termination_date,
  s.termination_reason,
  s.location_state,
  s.annual_salary_usd,
  s.hourly_rate_usd,
  s.loaded_at                                           AS last_snapshot_at
FROM `control-electoral-510800.staging.stg_employee_snapshots` AS s
JOIN `control-electoral-510800.gold.dim_employee_department_history` AS h
  ON h.employee_id = s.employee_id
 AND h.is_current
WHERE s.snapshot_rank = 1
  AND NOT s.is_test_account
;

ASSERT NOT EXISTS (SELECT employee_id FROM `control-electoral-510800.gold.dim_employee` GROUP BY employee_id HAVING COUNT(*) > 1) AS 'dim_employee: uniqueKey(employee_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.dim_employee` WHERE employee_id IS NULL) AS 'dim_employee: nonNull(employee_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.dim_employee` WHERE current_department_id IS NULL) AS 'dim_employee: nonNull(current_department_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.dim_employee` WHERE employment_type IS NULL) AS 'dim_employee: nonNull(employment_type) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.dim_employee` WHERE hire_date IS NULL) AS 'dim_employee: nonNull(hire_date) failed';

-- table: fct_employer_contributions
CREATE OR REPLACE TABLE `control-electoral-510800.gold.fct_employer_contributions`
PARTITION BY DATE_TRUNC(pay_date, MONTH)
CLUSTER BY department_id AS
WITH run_dates AS (
  SELECT pay_run_id, MAX(pay_date) AS pay_date
  FROM `control-electoral-510800.staging.stg_payroll_lines`
  GROUP BY pay_run_id
),

valid_line_department AS (
  SELECT pay_run_id, employee_id, ANY_VALUE(department_id) AS department_id
  FROM `control-electoral-510800.gold.fct_payroll_lines`
  GROUP BY pay_run_id, employee_id
),

any_line_department AS (
  -- Some employee/run pairs only have lines that were later voided; the employer still
  -- paid the contribution, so we keep it and charge the same cost center.
  SELECT pay_run_id, employee_id, ANY_VALUE(department_id) AS department_id
  FROM `control-electoral-510800.staging.stg_payroll_lines`
  WHERE ingestion_rank = 1
  GROUP BY pay_run_id, employee_id
),

contributions AS (
  SELECT *
  FROM `control-electoral-510800.staging.stg_employer_contributions`
  WHERE NOT is_test_account
  -- defensive de-duplication: the uniqueness of the raw key is asserted separately
  QUALIFY ROW_NUMBER() OVER (PARTITION BY pay_run_id, employee_id, contribution_type ORDER BY amount_usd DESC) = 1
)

SELECT
  CONCAT(c.pay_run_id, '|', c.employee_id, '|', c.contribution_type) AS contribution_id,
  c.pay_run_id,
  c.employee_id,
  COALESCE(v.department_id, a.department_id, h.department_id)      AS department_id,
  CASE
    WHEN v.department_id IS NOT NULL THEN 'VALID_LINES'
    WHEN a.department_id IS NOT NULL THEN 'RUN_LINES'
    ELSE 'HOME_DEPARTMENT'
  END                                                              AS department_source,
  r.pay_date,
  DATE_TRUNC(r.pay_date, MONTH)                                    AS pay_month,
  c.contribution_type,
  c.amount_usd
FROM contributions AS c
JOIN run_dates AS r
  ON r.pay_run_id = c.pay_run_id
LEFT JOIN valid_line_department AS v
  ON v.pay_run_id = c.pay_run_id AND v.employee_id = c.employee_id
LEFT JOIN any_line_department AS a
  ON a.pay_run_id = c.pay_run_id AND a.employee_id = c.employee_id
LEFT JOIN `control-electoral-510800.gold.dim_employee_department_history` AS h
  ON h.employee_id = c.employee_id
 AND r.pay_date BETWEEN h.valid_from AND h.valid_to
;

ASSERT NOT EXISTS (SELECT contribution_id FROM `control-electoral-510800.gold.fct_employer_contributions` GROUP BY contribution_id HAVING COUNT(*) > 1) AS 'fct_employer_contributions: uniqueKey(contribution_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_employer_contributions` WHERE contribution_id IS NULL) AS 'fct_employer_contributions: nonNull(contribution_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_employer_contributions` WHERE pay_run_id IS NULL) AS 'fct_employer_contributions: nonNull(pay_run_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_employer_contributions` WHERE employee_id IS NULL) AS 'fct_employer_contributions: nonNull(employee_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_employer_contributions` WHERE department_id IS NULL) AS 'fct_employer_contributions: nonNull(department_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_employer_contributions` WHERE pay_date IS NULL) AS 'fct_employer_contributions: nonNull(pay_date) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_employer_contributions` WHERE amount_usd IS NULL) AS 'fct_employer_contributions: nonNull(amount_usd) failed';

-- assertion: assert_employee_snapshots_consistent
ASSERT NOT EXISTS (
SELECT 'same_load_time_twice' AS problem, employee_id
FROM `control-electoral-510800.staging.stg_employee_snapshots`
GROUP BY employee_id, loaded_at
HAVING COUNT(*) > 1

UNION ALL

SELECT 'termination_before_hire', employee_id
FROM `control-electoral-510800.staging.stg_employee_snapshots`
WHERE termination_date < hire_date

UNION ALL

SELECT 'pay_rate_ambiguous', employee_id
FROM `control-electoral-510800.staging.stg_employee_snapshots`
WHERE employment_type <> 'CONTRACTOR'
  AND ((annual_salary_usd IS NULL) = (hourly_rate_usd IS NULL))

UNION ALL

SELECT 'hire_or_termination_changed_between_snapshots', employee_id
FROM `control-electoral-510800.staging.stg_employee_snapshots`
GROUP BY employee_id
HAVING COUNT(DISTINCT hire_date) > 1

UNION ALL

SELECT 'history_gap_or_overlap', employee_id
FROM (
  SELECT
    employee_id,
    valid_from,
    LAG(valid_to) OVER (PARTITION BY employee_id ORDER BY valid_from) AS previous_valid_to
  FROM `control-electoral-510800.gold.dim_employee_department_history`
)
WHERE previous_valid_to IS NOT NULL
  AND valid_from <> DATE_ADD(previous_valid_to, INTERVAL 1 DAY)

UNION ALL

SELECT 'department_still_missing', employee_id
FROM `control-electoral-510800.gold.dim_employee_department_history`
WHERE department_id IS NULL
) AS 'assert_employee_snapshots_consistent failed';

-- table: agg_salary_by_job_title
CREATE OR REPLACE TABLE `control-electoral-510800.gold.agg_salary_by_job_title` AS
WITH population AS (
  -- Active, full-time employees only: part-time pay cannot be annualised fairly and
  -- contractors are not on payroll.
  SELECT
    job_title,
    COALESCE(annual_salary_usd, hourly_rate_usd * 2080) AS annualized_pay_usd
  FROM `control-electoral-510800.gold.dim_employee`
  WHERE employment_type = 'FULL_TIME'
    AND (termination_date IS NULL OR termination_date > CURRENT_DATE())
),

by_title AS (
  SELECT
    job_title,
    COUNT(*)                                  AS employee_count,
    AVG(annualized_pay_usd)                   AS avg_pay,
    APPROX_QUANTILES(annualized_pay_usd, 2)[OFFSET(1)] AS median_pay
  FROM population
  GROUP BY job_title
)

SELECT
  job_title,
  employee_count,
  employee_count < 5 AS is_suppressed,
  IF(employee_count < 5, NULL, ROUND(avg_pay, -3))    AS avg_annualized_pay_usd,
  IF(employee_count < 5, NULL, ROUND(median_pay, -3)) AS median_annualized_pay_usd
FROM by_title
;

ASSERT NOT EXISTS (SELECT job_title FROM `control-electoral-510800.gold.agg_salary_by_job_title` GROUP BY job_title HAVING COUNT(*) > 1) AS 'agg_salary_by_job_title: uniqueKey(job_title) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.agg_salary_by_job_title` WHERE NOT (is_suppressed OR employee_count >= 5)) AS 'agg_salary_by_job_title: rowCondition failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.agg_salary_by_job_title` WHERE NOT (NOT is_suppressed OR avg_annualized_pay_usd IS NULL)) AS 'agg_salary_by_job_title: rowCondition failed';

-- table: dim_department
CREATE OR REPLACE TABLE `control-electoral-510800.gold.dim_department` AS
SELECT
  d.department_id,
  d.department_name,
  d.division,
  d.cost_center,
  d.manager_employee_id,
  e.full_name AS manager_name
FROM `control-electoral-510800.staging.stg_departments` AS d
LEFT JOIN `control-electoral-510800.gold.dim_employee` AS e
  ON e.employee_id = d.manager_employee_id
;

ASSERT NOT EXISTS (SELECT department_id FROM `control-electoral-510800.gold.dim_department` GROUP BY department_id HAVING COUNT(*) > 1) AS 'dim_department: uniqueKey(department_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.dim_department` WHERE department_id IS NULL) AS 'dim_department: nonNull(department_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.dim_department` WHERE department_name IS NULL) AS 'dim_department: nonNull(department_name) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.dim_department` WHERE division IS NULL) AS 'dim_department: nonNull(division) failed';

-- table: fct_payroll_cost
CREATE OR REPLACE TABLE `control-electoral-510800.gold.fct_payroll_cost`
PARTITION BY DATE_TRUNC(pay_date, MONTH)
CLUSTER BY department_id, cost_category AS
SELECT
  CONCAT('L|', payroll_line_id) AS cost_component_id,
  'EARNINGS'                    AS cost_category,
  earning_type                  AS cost_type,
  payroll_line_id,
  pay_run_id,
  employee_id,
  department_id,
  pay_date,
  pay_month,
  hours,
  amount_usd
FROM `control-electoral-510800.gold.fct_payroll_lines`

UNION ALL

SELECT
  CONCAT('C|', contribution_id),
  'EMPLOYER_CONTRIBUTION',
  contribution_type,
  CAST(NULL AS STRING),
  pay_run_id,
  employee_id,
  department_id,
  pay_date,
  pay_month,
  CAST(NULL AS NUMERIC),
  amount_usd
FROM `control-electoral-510800.gold.fct_employer_contributions`
;

ASSERT NOT EXISTS (SELECT cost_component_id FROM `control-electoral-510800.gold.fct_payroll_cost` GROUP BY cost_component_id HAVING COUNT(*) > 1) AS 'fct_payroll_cost: uniqueKey(cost_component_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_payroll_cost` WHERE cost_component_id IS NULL) AS 'fct_payroll_cost: nonNull(cost_component_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_payroll_cost` WHERE cost_category IS NULL) AS 'fct_payroll_cost: nonNull(cost_category) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_payroll_cost` WHERE cost_type IS NULL) AS 'fct_payroll_cost: nonNull(cost_type) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_payroll_cost` WHERE department_id IS NULL) AS 'fct_payroll_cost: nonNull(department_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_payroll_cost` WHERE pay_date IS NULL) AS 'fct_payroll_cost: nonNull(pay_date) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_payroll_cost` WHERE amount_usd IS NULL) AS 'fct_payroll_cost: nonNull(amount_usd) failed';

-- table: fct_terminations
CREATE OR REPLACE TABLE `control-electoral-510800.gold.fct_terminations` AS
SELECT
  e.employee_id,
  e.termination_date,
  DATE_TRUNC(e.termination_date, MONTH)     AS termination_month,
  e.termination_reason,
  e.termination_reason = 'VOLUNTARY'        AS is_voluntary,
  h.department_id,
  e.employment_type,
  e.job_title,
  DATE_DIFF(e.termination_date, e.hire_date, DAY) / 365.25 AS tenure_years
FROM `control-electoral-510800.gold.dim_employee` AS e
JOIN `control-electoral-510800.gold.dim_employee_department_history` AS h
  ON h.employee_id = e.employee_id
 AND e.termination_date BETWEEN h.valid_from AND h.valid_to
WHERE e.termination_date IS NOT NULL
  AND e.is_headcount_eligible
;

ASSERT NOT EXISTS (SELECT employee_id FROM `control-electoral-510800.gold.fct_terminations` GROUP BY employee_id HAVING COUNT(*) > 1) AS 'fct_terminations: uniqueKey(employee_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_terminations` WHERE employee_id IS NULL) AS 'fct_terminations: nonNull(employee_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_terminations` WHERE termination_date IS NULL) AS 'fct_terminations: nonNull(termination_date) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_terminations` WHERE termination_reason IS NULL) AS 'fct_terminations: nonNull(termination_reason) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_terminations` WHERE department_id IS NULL) AS 'fct_terminations: nonNull(department_id) failed';

-- table: fct_workforce_month_end
CREATE OR REPLACE TABLE `control-electoral-510800.gold.fct_workforce_month_end` AS
WITH bounds AS (
  -- Reporting window = months covered by payroll data (Jul 2025 - Sep 2026 today).
  SELECT DATE_TRUNC(MIN(pay_date), MONTH) AS first_month, DATE_TRUNC(MAX(pay_date), MONTH) AS last_month
  FROM `control-electoral-510800.gold.fct_payroll_lines`
),

months AS (
  SELECT LAST_DAY(m, MONTH) AS month_end_date
  FROM bounds, UNNEST(GENERATE_DATE_ARRAY(first_month, last_month, INTERVAL 1 MONTH)) AS m
)

SELECT
  e.employee_id,
  m.month_end_date,
  DATE_TRUNC(m.month_end_date, MONTH) AS month_start_date,
  h.department_id,
  e.employment_type,
  e.flsa_status,
  e.job_title
FROM months AS m
JOIN `control-electoral-510800.gold.dim_employee` AS e
  ON e.is_headcount_eligible
 AND e.hire_date <= m.month_end_date
 AND (e.termination_date IS NULL OR e.termination_date > m.month_end_date)
JOIN `control-electoral-510800.gold.dim_employee_department_history` AS h
  ON h.employee_id = e.employee_id
 AND m.month_end_date BETWEEN h.valid_from AND h.valid_to
;

ASSERT NOT EXISTS (SELECT employee_id, month_end_date FROM `control-electoral-510800.gold.fct_workforce_month_end` GROUP BY employee_id, month_end_date HAVING COUNT(*) > 1) AS 'fct_workforce_month_end: uniqueKey(employee_id, month_end_date) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_workforce_month_end` WHERE employee_id IS NULL) AS 'fct_workforce_month_end: nonNull(employee_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_workforce_month_end` WHERE month_end_date IS NULL) AS 'fct_workforce_month_end: nonNull(month_end_date) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.fct_workforce_month_end` WHERE department_id IS NULL) AS 'fct_workforce_month_end: nonNull(department_id) failed';

-- table: agg_department_monthly
CREATE OR REPLACE TABLE `control-electoral-510800.gold.agg_department_monthly` AS
WITH bounds AS (
  SELECT DATE_TRUNC(MIN(pay_date), MONTH) AS first_month, DATE_TRUNC(MAX(pay_date), MONTH) AS last_month
  FROM `control-electoral-510800.gold.fct_payroll_lines`
),

spine AS (
  SELECT d.department_id, m AS month_start_date
  FROM `control-electoral-510800.gold.dim_department` AS d
  CROSS JOIN bounds
  CROSS JOIN UNNEST(GENERATE_DATE_ARRAY(bounds.first_month, bounds.last_month, INTERVAL 1 MONTH)) AS m
),

pay_runs AS (
  -- Biweekly payroll: most months have 2 pay dates, two months a year have 3.
  -- Because gross payroll is assigned to the month of pay_date, those months look
  -- ~50% more expensive. Exposed so the dashboard can flag them.
  SELECT pay_month AS month_start_date, COUNT(DISTINCT pay_run_id) AS pay_runs_in_month
  FROM `control-electoral-510800.gold.fct_payroll_lines`
  GROUP BY 1
),

earnings AS (
  SELECT
    department_id,
    pay_month AS month_start_date,
    SUM(amount_usd)                                           AS gross_payroll_usd,
    SUM(IF(earning_type = 'REGULAR',  amount_usd, 0))         AS regular_earnings_usd,
    SUM(IF(earning_type = 'OVERTIME', amount_usd, 0))         AS overtime_earnings_usd,
    SUM(IF(earning_type = 'PTO',      amount_usd, 0))         AS pto_earnings_usd,
    SUM(IF(earning_type = 'BONUS',    amount_usd, 0))         AS bonus_earnings_usd,
    SUM(IF(earning_type = 'OVERTIME', hours, 0))              AS overtime_hours,
    SUM(IF(earning_type = 'REGULAR',  hours, 0))              AS regular_hours
  FROM `control-electoral-510800.gold.fct_payroll_lines`
  GROUP BY 1, 2
),

contributions AS (
  SELECT
    department_id,
    pay_month AS month_start_date,
    SUM(amount_usd)                                                 AS employer_cost_usd,
    SUM(IF(contribution_type = 'FICA', amount_usd, 0))              AS fica_usd,
    SUM(IF(contribution_type = 'HEALTH_INSURANCE', amount_usd, 0))  AS health_insurance_usd,
    SUM(IF(contribution_type = 'RETIREMENT_MATCH', amount_usd, 0))  AS retirement_match_usd
  FROM `control-electoral-510800.gold.fct_employer_contributions`
  GROUP BY 1, 2
),

headcount AS (
  SELECT
    department_id,
    month_start_date,
    COUNT(*)                                     AS headcount_month_end,
    COUNTIF(employment_type = 'FULL_TIME')       AS full_time_headcount_month_end,
    COUNTIF(employment_type = 'PART_TIME')       AS part_time_headcount_month_end
  FROM `control-electoral-510800.gold.fct_workforce_month_end`
  GROUP BY 1, 2
),

terminations AS (
  SELECT
    department_id,
    termination_month AS month_start_date,
    COUNTIF(is_voluntary)  AS voluntary_terminations,
    COUNT(*)               AS total_terminations
  FROM `control-electoral-510800.gold.fct_terminations`
  GROUP BY 1, 2
),

base AS (
  SELECT
    s.department_id,
    s.month_start_date,
    COALESCE(e.gross_payroll_usd, 0)          AS gross_payroll_usd,
    COALESCE(e.regular_earnings_usd, 0)       AS regular_earnings_usd,
    COALESCE(e.overtime_earnings_usd, 0)      AS overtime_earnings_usd,
    COALESCE(e.pto_earnings_usd, 0)           AS pto_earnings_usd,
    COALESCE(e.bonus_earnings_usd, 0)         AS bonus_earnings_usd,
    COALESCE(e.overtime_hours, 0)             AS overtime_hours,
    COALESCE(e.regular_hours, 0)              AS regular_hours,
    COALESCE(c.employer_cost_usd, 0)          AS employer_cost_usd,
    COALESCE(c.fica_usd, 0)                   AS fica_usd,
    COALESCE(c.health_insurance_usd, 0)       AS health_insurance_usd,
    COALESCE(c.retirement_match_usd, 0)       AS retirement_match_usd,
    COALESCE(h.headcount_month_end, 0)        AS headcount_month_end,
    COALESCE(h.full_time_headcount_month_end, 0) AS full_time_headcount_month_end,
    COALESCE(h.part_time_headcount_month_end, 0) AS part_time_headcount_month_end,
    COALESCE(t.voluntary_terminations, 0)     AS voluntary_terminations,
    COALESCE(t.total_terminations, 0)         AS total_terminations,
    b.budgeted_gross_payroll_usd,
    b.budgeted_headcount
  FROM spine AS s
  LEFT JOIN earnings      AS e USING (department_id, month_start_date)
  LEFT JOIN contributions AS c USING (department_id, month_start_date)
  LEFT JOIN headcount     AS h USING (department_id, month_start_date)
  LEFT JOIN terminations  AS t USING (department_id, month_start_date)
  LEFT JOIN `control-electoral-510800.gold.fct_budget_monthly` AS b USING (department_id, month_start_date)
)

SELECT
  CONCAT(cur.department_id, '|', FORMAT_DATE('%Y-%m', cur.month_start_date)) AS department_month_key,
  cur.*,
  cur.gross_payroll_usd + cur.employer_cost_usd             AS fully_loaded_cost_usd,
  pr.pay_runs_in_month,
  LAST_DAY(cur.month_start_date, MONTH)                      AS month_end_date,
  cal.fiscal_year,
  cal.fiscal_year_num,
  cal.fiscal_quarter,
  cal.fiscal_quarter_num,
  cal.fiscal_period,
  cal.is_fiscal_quarter_end_month,
  cal.is_fiscal_year_end_month,

  -- Prior-period comparison columns (NULL when the earlier month is outside the data window).
  pq.gross_payroll_usd                                       AS gross_payroll_usd_prior_quarter,
  pq.overtime_earnings_usd                                   AS overtime_earnings_usd_prior_quarter,
  pq.gross_payroll_usd + pq.employer_cost_usd                AS fully_loaded_cost_usd_prior_quarter,
  pq.headcount_month_end                                     AS headcount_month_end_prior_quarter,
  pq.voluntary_terminations                                  AS voluntary_terminations_prior_quarter,
  py.gross_payroll_usd                                       AS gross_payroll_usd_prior_year,
  py.overtime_earnings_usd                                   AS overtime_earnings_usd_prior_year,
  py.gross_payroll_usd + py.employer_cost_usd                AS fully_loaded_cost_usd_prior_year,
  py.headcount_month_end                                     AS headcount_month_end_prior_year,
  py.voluntary_terminations                                  AS voluntary_terminations_prior_year
FROM base AS cur
JOIN `control-electoral-510800.gold.dim_fiscal_calendar` AS cal
  ON cal.calendar_date = cur.month_start_date
LEFT JOIN pay_runs AS pr
  ON pr.month_start_date = cur.month_start_date
LEFT JOIN base AS pq
  ON pq.department_id = cur.department_id
 AND pq.month_start_date = DATE_SUB(cur.month_start_date, INTERVAL 3 MONTH)
LEFT JOIN base AS py
  ON py.department_id = cur.department_id
 AND py.month_start_date = DATE_SUB(cur.month_start_date, INTERVAL 12 MONTH)
;

ASSERT NOT EXISTS (SELECT department_month_key FROM `control-electoral-510800.gold.agg_department_monthly` GROUP BY department_month_key HAVING COUNT(*) > 1) AS 'agg_department_monthly: uniqueKey(department_month_key) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.agg_department_monthly` WHERE department_month_key IS NULL) AS 'agg_department_monthly: nonNull(department_month_key) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.agg_department_monthly` WHERE department_id IS NULL) AS 'agg_department_monthly: nonNull(department_id) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.agg_department_monthly` WHERE month_start_date IS NULL) AS 'agg_department_monthly: nonNull(month_start_date) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.agg_department_monthly` WHERE fiscal_year IS NULL) AS 'agg_department_monthly: nonNull(fiscal_year) failed';
ASSERT NOT EXISTS (SELECT 1 FROM `control-electoral-510800.gold.agg_department_monthly` WHERE fiscal_quarter IS NULL) AS 'agg_department_monthly: nonNull(fiscal_quarter) failed';

-- assertion: assert_gold_excludes_invalid_lines
ASSERT NOT EXISTS (
WITH voided AS (
  SELECT DISTINCT voids_line_id AS payroll_line_id
  FROM `control-electoral-510800.staging.stg_payroll_lines`
  WHERE line_status = 'VOID' AND ingestion_rank = 1
)

SELECT 'cancelled_line_in_gold' AS problem, f.payroll_line_id
FROM `control-electoral-510800.gold.fct_payroll_lines` AS f
JOIN voided AS v USING (payroll_line_id)

UNION ALL

SELECT 'test_account_in_gold', employee_id
FROM `control-electoral-510800.gold.fct_payroll_cost`
WHERE STARTS_WITH(employee_id, 'TEST')

UNION ALL

SELECT 'test_account_in_dim_employee', employee_id
FROM `control-electoral-510800.gold.dim_employee`
WHERE STARTS_WITH(employee_id, 'TEST')

UNION ALL

SELECT 'void_or_unknown_status_in_gold', l.payroll_line_id
FROM `control-electoral-510800.gold.fct_payroll_lines` AS f
JOIN `control-electoral-510800.staging.stg_payroll_lines` AS l
  ON l.payroll_line_id = f.payroll_line_id AND l.ingestion_rank = 1
WHERE l.line_status <> 'POSTED'
) AS 'assert_gold_excludes_invalid_lines failed';

-- assertion: assert_budget_coverage
ASSERT NOT EXISTS (
SELECT 'actuals_without_budget' AS problem, department_month_key AS record_id
FROM `control-electoral-510800.gold.agg_department_monthly`
WHERE gross_payroll_usd > 0 AND budgeted_gross_payroll_usd IS NULL

UNION ALL

SELECT 'duplicate_budget_row', CONCAT(department_id, '|', CAST(month_start_date AS STRING))
FROM `control-electoral-510800.staging.stg_budget`
GROUP BY department_id, month_start_date
HAVING COUNT(*) > 1

UNION ALL

SELECT 'budget_fiscal_label_mismatch', CONCAT(b.department_id, '|', CAST(b.month_start_date AS STRING))
FROM `control-electoral-510800.staging.stg_budget` AS b
JOIN `control-electoral-510800.gold.dim_fiscal_calendar` AS c
  ON c.calendar_date = b.month_start_date
WHERE b.fiscal_year <> c.fiscal_year OR b.fiscal_period <> c.fiscal_period
) AS 'assert_budget_coverage failed';

-- assertion: assert_gold_reconciles
ASSERT NOT EXISTS (
WITH checks AS (
  SELECT 'gross_payroll' AS metric,
         (SELECT SUM(gross_payroll_usd) FROM `control-electoral-510800.gold.agg_department_monthly`) AS agg_value,
         (SELECT SUM(amount_usd) FROM `control-electoral-510800.gold.fct_payroll_lines`)             AS fact_value
  UNION ALL
  SELECT 'employer_cost',
         (SELECT SUM(employer_cost_usd) FROM `control-electoral-510800.gold.agg_department_monthly`),
         (SELECT SUM(amount_usd) FROM `control-electoral-510800.gold.fct_employer_contributions`)
  UNION ALL
  SELECT 'payroll_cost_union',
         (SELECT SUM(amount_usd) FROM `control-electoral-510800.gold.fct_payroll_cost`),
         (SELECT SUM(amount_usd) FROM `control-electoral-510800.gold.fct_payroll_lines`)
           + (SELECT SUM(amount_usd) FROM `control-electoral-510800.gold.fct_employer_contributions`)
  UNION ALL
  SELECT 'headcount_rows',
         (SELECT SUM(headcount_month_end) FROM `control-electoral-510800.gold.agg_department_monthly`),
         (SELECT COUNT(*) FROM `control-electoral-510800.gold.fct_workforce_month_end`)
  UNION ALL
  SELECT 'contributions_kept',
         (SELECT COUNT(*) FROM `control-electoral-510800.gold.fct_employer_contributions`),
         (SELECT COUNT(*) FROM `control-electoral-510800.staging.stg_employer_contributions` WHERE NOT is_test_account)
)

SELECT *
FROM checks
WHERE ABS(COALESCE(agg_value, 0) - COALESCE(fact_value, 0)) > 0.01
) AS 'assert_gold_reconciles failed';

-- operations: etl_run_log (Looker datagroup trigger)
CREATE TABLE IF NOT EXISTS `control-electoral-510800.gold.etl_run_log` (
  run_finished_at TIMESTAMP NOT NULL,
  valid_payroll_lines INT64,
  max_pay_date DATE
);

INSERT INTO `control-electoral-510800.gold.etl_run_log` (run_finished_at, valid_payroll_lines, max_pay_date)
SELECT CURRENT_TIMESTAMP(), COUNT(*), MAX(pay_date)
FROM `control-electoral-510800.gold.fct_payroll_lines`;

-- =============================== ANSWERS ===============================
-- Q1 Fully loaded payroll cost in FY2026
SELECT
  fiscal_year,
  ROUND(SUM(gross_payroll_usd), 2)                       AS gross_payroll_usd,
  ROUND(SUM(employer_cost_usd), 2)                       AS employer_cost_usd,
  ROUND(SUM(gross_payroll_usd + employer_cost_usd), 2)   AS fully_loaded_cost_usd
FROM `control-electoral-510800.gold.agg_department_monthly`
WHERE fiscal_year = 'FY2026'
GROUP BY fiscal_year;

-- Q2 Overtime % by department in Q1 FY2027 (July to September 2026)
SELECT
  d.department_name,
  ROUND(SUM(a.overtime_earnings_usd), 2)                                  AS overtime_usd,
  ROUND(SUM(a.gross_payroll_usd), 2)                                      AS gross_payroll_usd,
  ROUND(100 * SUM(a.overtime_earnings_usd) / SUM(a.gross_payroll_usd), 2) AS overtime_pct
FROM `control-electoral-510800.gold.agg_department_monthly` AS a
JOIN `control-electoral-510800.gold.dim_department` AS d USING (department_id)
WHERE a.fiscal_quarter = 'FY2027-Q1'
GROUP BY d.department_name
ORDER BY overtime_pct DESC;

-- Q3 Voluntary turnover rate in FY2026
SELECT
  SUM(voluntary_terminations)                                               AS voluntary_terminations,
  SUM(headcount_month_end) / COUNT(DISTINCT month_start_date)               AS avg_month_end_headcount,
  ROUND(100 * SUM(voluntary_terminations)
        / (SUM(headcount_month_end) / COUNT(DISTINCT month_start_date)), 2) AS voluntary_turnover_pct
FROM `control-electoral-510800.gold.agg_department_monthly`
WHERE fiscal_year = 'FY2026';

-- Q4 Headcount on September 30, 2026
SELECT
  month_end_date,
  SUM(headcount_month_end)            AS headcount,
  SUM(full_time_headcount_month_end)  AS full_time,
  SUM(part_time_headcount_month_end)  AS part_time
FROM `control-electoral-510800.gold.agg_department_monthly`
WHERE month_end_date = DATE '2026-09-30'
GROUP BY month_end_date;
